static bool read_file(const std::string& path, std::vector<unsigned char>& bytes) { std::ifstream f(path, std::ios::binary); if (!f) return false; bytes.assign(std::istreambuf_iterator<char>(f), {}); return true; }
static bool unchanged(const PortableEntryBinding& a, const PortableEntryBinding& b) { return std::memcmp(&a, &b, sizeof(a)) == 0; }
static std::array<unsigned char,32> digest() { std::array<unsigned char,32> x{}; for (unsigned i=0;i<x.size();++i) x[i]=static_cast<unsigned char>(i+1); return x; }
static bool exact_valid(const PortableEntryBinding& x, bool leading_zero = false) {
    if (x.module_count != 3 || x.trusted_manifest_digest != digest() || x.relocation_digest != digest() || x.source_self_digest != digest() || x.canonical_file_digest != digest()) return false;
    for (unsigned i=0;i<3;++i) { const auto& m=x.modules[i]; auto expected=digest(); if (leading_zero && i==0) { for (unsigned j=0;j<8;++j) expected[j]=0; expected[8]=1; } if (m.id != static_cast<GuestModuleId>(i) || m.image_size!=0x1000 || m.writable_begin!=0x100 || m.writable_size!=0x200 || m.dt_init!=0x40 || m.ctor_flag!=0x100 || m.init_array!=0x200 || m.init_array_size!=0x20 || m.carrier_size!=1 || m.carrier_digest!=expected) return false; }
    return x.nn_init_start.provider==2 && x.nn_init_start.offset==0x80 && x.nn_main.provider==0 && x.nn_main.offset==0x84;
}
int main(int argc, char** argv) { std::cout.setf(std::ios::unitbuf); int checks=0; bool all=true; auto check=[&](const std::string& n,bool p){++checks; std::cout<<"test="<<n<<" result="<<(p?"PASS":"FAIL")<<'\n'; all&=p;};
    PortableEntryBinding sentinel{}; sentinel.module_count=0xdeadbeefu; std::memset(sentinel.trusted_manifest_digest.data(),0xa5,32); PortableEntryBinding out=sentinel;
    check("null",read_entry_binding(nullptr,out)==EntryBindingReadResult::null_input&&unchanged(out,sentinel));
#ifdef ENTRY_BINDING_READER_TESTING
    const unsigned char empty[]=""; const unsigned char abc[]="abc"; const unsigned char payload[]="synthetic payload";
    check("sha_empty",entry_binding_test_sha256(empty,0)==std::array<unsigned char,32>{0xe3,0xb0,0xc4,0x42,0x98,0xfc,0x1c,0x14,0x9a,0xfb,0xf4,0xc8,0x99,0x6f,0xb9,0x24,0x27,0xae,0x41,0xe4,0x64,0x9b,0x93,0x4c,0xa4,0x95,0x99,0x1b,0x78,0x52,0xb8,0x55});
    check("sha_abc",entry_binding_test_sha256(abc,3)==std::array<unsigned char,32>{0xba,0x78,0x16,0xbf,0x8f,0x01,0xcf,0xea,0x41,0x41,0x40,0xde,0x5d,0xae,0x22,0x23,0xb0,0x03,0x61,0xa3,0x96,0x17,0x7a,0x9c,0xb4,0x10,0xff,0x61,0xf2,0x00,0x15,0xad});
    check("sha_payload",entry_binding_test_sha256(payload,sizeof(payload)-1)==std::array<unsigned char,32>{0x2d,0x7c,0x09,0x18,0x8d,0x41,0x4c,0x88,0x8f,0x37,0xb6,0x61,0xe2,0x7a,0xec,0xdd,0x54,0x23,0x1e,0x02,0x7e,0xa2,0xc8,0xad,0x9c,0x1e,0x31,0x3a,0xab,0x34,0xc5,0xd9});
#endif
    std::vector<std::string> names={"valid","carrier_digest_leading_zero"};
    std::vector<std::pair<std::string,EntryBindingReadResult>> rejected={{"truncated_0",EntryBindingReadResult::truncated},{"truncated_159",EntryBindingReadResult::truncated},{"truncated_160",EntryBindingReadResult::truncated},{"truncated_335",EntryBindingReadResult::truncated},{"truncated_791",EntryBindingReadResult::truncated},{"trailing",EntryBindingReadResult::trailing_bytes},{"payload_digest",EntryBindingReadResult::bad_digest},{"magic",EntryBindingReadResult::bad_magic},{"version",EntryBindingReadResult::bad_magic},{"version_reserved",EntryBindingReadResult::bad_magic},{"count",EntryBindingReadResult::bad_header},{"total",EntryBindingReadResult::bad_header},{"header_identity_0",EntryBindingReadResult::bad_identity},{"header_identity_1",EntryBindingReadResult::bad_identity},{"header_identity_2",EntryBindingReadResult::bad_identity},{"header_identity_3",EntryBindingReadResult::bad_identity},{"header_reserved",EntryBindingReadResult::bad_reserved},{"module_role_0",EntryBindingReadResult::bad_order},{"module_id_1",EntryBindingReadResult::bad_order},{"module_reserved",EntryBindingReadResult::bad_reserved},{"module_tail",EntryBindingReadResult::bad_reserved},{"module_identity",EntryBindingReadResult::bad_reserved},{"carrier_size",EntryBindingReadResult::bad_reserved},{"carrier_digest_0",EntryBindingReadResult::bad_reserved},{"carrier_digest_1",EntryBindingReadResult::bad_reserved},{"carrier_digest_2",EntryBindingReadResult::bad_reserved},{"image_zero",EntryBindingReadResult::bad_geometry},{"writable_zero",EntryBindingReadResult::bad_geometry},{"writable_overflow",EntryBindingReadResult::bad_geometry},{"writable_beyond",EntryBindingReadResult::bad_geometry},{"dt_zero",EntryBindingReadResult::bad_geometry},{"dt_misaligned",EntryBindingReadResult::bad_geometry},{"dt_out",EntryBindingReadResult::bad_geometry},{"ctor_misaligned",EntryBindingReadResult::bad_geometry},{"ctor_before",EntryBindingReadResult::bad_geometry},{"ctor_end",EntryBindingReadResult::bad_geometry},{"init_mixed_zero_a",EntryBindingReadResult::bad_init_array},{"init_mixed_zero_b",EntryBindingReadResult::bad_init_array},{"init_alignment_offset",EntryBindingReadResult::bad_init_array},{"init_alignment_size",EntryBindingReadResult::bad_init_array},{"init_overflow",EntryBindingReadResult::bad_init_array},{"init_beyond",EntryBindingReadResult::bad_init_array},{"entry_provider_0",EntryBindingReadResult::bad_provider},{"entry_provider_1",EntryBindingReadResult::bad_provider},{"entry_range_0",EntryBindingReadResult::bad_entry},{"entry_range_1",EntryBindingReadResult::bad_entry},{"entry_alignment_0",EntryBindingReadResult::bad_entry},{"entry_alignment_1",EntryBindingReadResult::bad_entry},{"provider_policy_0",EntryBindingReadResult::bad_provider},{"provider_policy_1",EntryBindingReadResult::bad_provider},{"entry_identity_0",EntryBindingReadResult::bad_reserved},{"entry_identity_1",EntryBindingReadResult::bad_reserved},{"entry_reserved_0",EntryBindingReadResult::bad_reserved},{"entry_reserved_1",EntryBindingReadResult::bad_reserved},{"entry_tail_0",EntryBindingReadResult::bad_reserved},{"entry_tail_1",EntryBindingReadResult::bad_reserved},{"dt_alias",EntryBindingReadResult::bad_alias},{"ctor_alias",EntryBindingReadResult::bad_alias},{"init_alias",EntryBindingReadResult::bad_alias},{"entry_distinction",EntryBindingReadResult::bad_provider}};
    for (const auto& e:{EntryBindingReadResult::ok,EntryBindingReadResult::null_input,EntryBindingReadResult::io_error,EntryBindingReadResult::truncated,EntryBindingReadResult::trailing_bytes,EntryBindingReadResult::bad_magic,EntryBindingReadResult::bad_header,EntryBindingReadResult::bad_reserved,EntryBindingReadResult::bad_digest,EntryBindingReadResult::bad_identity,EntryBindingReadResult::bad_order,EntryBindingReadResult::bad_geometry,EntryBindingReadResult::bad_alignment,EntryBindingReadResult::bad_init_array,EntryBindingReadResult::bad_entry,EntryBindingReadResult::bad_provider,EntryBindingReadResult::bad_alias}) check(std::string("safe_name_")+entry_binding_read_result_name(e),std::strcmp(entry_binding_read_result_name(e),"unknown_result")!=0);
    check("safe_name_unknown",std::strcmp(entry_binding_read_result_name(static_cast<EntryBindingReadResult>(255)),"unknown_result")==0);
    if(argc<2){check("fixture_directory",false);return 1;} std::set<std::string> expected(names.begin(),names.end()); for(auto&e:rejected)expected.insert(e.first); std::set<std::string> actual; for(auto& p:std::filesystem::directory_iterator(argv[1])) if(p.is_regular_file()) actual.insert(p.path().filename().string()); check("fixture_manifest_exact",actual==expected);
    auto run=[&](const std::string& name,EntryBindingReadResult want,bool valid){std::vector<unsigned char>b;bool loaded=read_file(std::string(argv[1])+"/"+name,b);FILE*f=nullptr;if(loaded){f=std::tmpfile();std::fwrite(b.data(),1,b.size(),f);std::rewind(f);}PortableEntryBinding before=sentinel,got=sentinel;auto r=read_entry_binding(f,got);if(f)std::fclose(f);check(name,loaded&&r==want&&(valid?exact_valid(got,name=="carrier_digest_leading_zero"):unchanged(got,before)));};
    run("valid",EntryBindingReadResult::ok,true); run("carrier_digest_leading_zero",EntryBindingReadResult::ok,true); for(auto&e:rejected)run(e.first,e.second,false);
    if(argc>2){std::vector<unsigned char>b;bool loaded=read_file(argv[2],b);FILE*f=nullptr;if(loaded){f=std::tmpfile();std::fwrite(b.data(),1,b.size(),f);std::rewind(f);}PortableEntryBinding got{};auto r=read_entry_binding(f,got);if(f)std::fclose(f);check("real_transport",loaded&&r==EntryBindingReadResult::ok);}
    std::cout<<"summary: "<<checks<<" checks, "<<(all?"PASS":"FAIL")<<'\n'; return all?0:1;
}
